export type TlsInfo = TlsInfo_Serialize | TlsInfo_Deserialize;

/**  TLS facts for an intercepted connection, shared by every flow on it. */
export type TlsInfo_Deserialize = {
	/**  Server name the client sent, if any (IP literals have none). */
	sni?: string | null,
	/**  ALPN protocols the client offered, in its order. */
	client_alpn: string[],
	/**  Protocol negotiated with the upstream and mirrored to the client. */
	alpn?: string | null,
	/**
	 *  Upstream protocol version, e.g. `TLSv1.3`. Empty if the upstream
	 *  handshake failed.
	 */
	version: string,
	/**  Upstream cipher suite, e.g. `TLS13_AES_128_GCM_SHA256`. */
	cipher: string,
	/**
	 *  False if the upstream certificate was accepted without verification
	 *  (the host is in the "allow insecure upstream" list).
	 */
	upstream_verified: boolean,
	/**  The upstream's certificate chain, leaf first. */
	chain: CertSummary[],
};

/**  TLS facts for an intercepted connection, shared by every flow on it. */
export type TlsInfo_Serialize = {
	/**  Server name the client sent, if any (IP literals have none). */
	sni: string | null,
	/**  ALPN protocols the client offered, in its order. */
	client_alpn: string[],
	/**  Protocol negotiated with the upstream and mirrored to the client. */
	alpn: string | null,
	/**
	 *  Upstream protocol version, e.g. `TLSv1.3`. Empty if the upstream
	 *  handshake failed.
	 */
	version: string,
	/**  Upstream cipher suite, e.g. `TLS13_AES_128_GCM_SHA256`. */
	cipher: string,
	/**
	 *  False if the upstream certificate was accepted without verification
	 *  (the host is in the "allow insecure upstream" list).
	 */
	upstream_verified: boolean,
	/**  The upstream's certificate chain, leaf first. */
	chain: CertSummary[],
};

/**  How a flow's TLS was handled. Drives the SSL column. */
export type TlsStatus = 
/**  Plain HTTP. */
"none" | 
/**  Decrypted by the MITM. */
"intercepted" | 
/**  CONNECT relayed without decrypting (SSL exclude list or bypass). */
"passthrough" | 
/**
 *  The client rejected our certificate (an `unknown_ca`/`bad_certificate`
 *  alert, or a close before any request). Either the Proxymate CA isn't
 *  trusted by that client or the app pins its certificates.
 */
"likely_pinned";

/**  CA trust as the certificate wizard and the toolbar show it. */
export type TrustStatus = TrustStatus_Serialize | TrustStatus_Deserialize;

/**  CA trust as the certificate wizard and the toolbar show it. */
export type TrustStatus_Deserialize = {
	keychain: KeychainTrust,
	/**
	 *  A real handshake through our own MITM, checked with the OS verifier,
	 *  succeeded. This is what browsers will see.
	 */
	verified: boolean,
	/**  Why verification failed, if it did. */
	detail?: string | null,
};

/**  CA trust as the certificate wizard and the toolbar show it. */
export type TrustStatus_Serialize = {
	keychain: KeychainTrust,
	/**
	 *  A real handshake through our own MITM, checked with the OS verifier,
	 *  succeeded. This is what browsers will see.
	 */
	verified: boolean,
	/**  Why verification failed, if it did. */
	detail: string | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

/**
 *  Per-tick change notification for one view, published at 20 Hz.
 * 
 *  The UI never receives rows in a delta; it re-fetches the visible window
 *  with `get_rows` when the delta says something in it may have changed.
 */
export type ViewDelta = {
	view: number,
	/**  Monotonic per-view sequence number, starting at 1. */
	seq: number,
	/**  Flows in the store (unfiltered). */
	total: number,
	/**  Rows in the view after this tick. */
	len: number,
	/**  Rows appended at the end of the view since the previous tick. */
	appended: number,
	/**  Ids of flows already in the view whose summary changed. */
	changed: number[],
	/**  Rows were inserted, removed or reordered: drop every cached row. */
	structural: boolean,
};

/**  Result of creating a view or changing its filter or sort. */
export type ViewInfo = {
	view: number,
	total: number,
	len: number,
	/**  Time the engine spent refiltering and sorting, in microseconds. */
	elapsed_us: number,
};

/**  How a WebSocket connection ended. */
export type WsClose = {
	/**
	 *  The close code, or `1005` for a close frame without one and `1006` for
	 *  a connection that dropped without any close frame (neither is ever
	 *  sent on the wire).
	 */
	code: number,
	reason: string,
	/**  The side that closed first. */
	by: WsDirection,
};

/**  Which way a WebSocket message went. */
export type WsDirection = 
/**  Client to server. */
"sent" | 
/**  Server to client. */
"received";

/**
 *  One WebSocket message (fragmented messages are reassembled). The payload
 *  itself is fetched with `websocket_payload`.
 */
export type WsMessage = WsMessage_Serialize | WsMessage_Deserialize;

/**
 *  One WebSocket message (fragmented messages are reassembled). The payload
 *  itself is fetched with `websocket_payload`.
 */
export type WsMessage_Deserialize = {
	/**  Position in the flow's message list, from 0. */
	index: number,
	direction: WsDirection,
	opcode: WsOpcode,
	/**  Payload size in bytes. For close frames, the reason only. */
	len: number,
	/**  When the proxy received it, milliseconds since the Unix epoch. */
	time_ms: number | null,
	/**
	 *  True if only the first part of the payload was recorded (the cap is
	 *  1 MB per message). Forwarding is unaffected.
	 */
	truncated: boolean,
	/**  Status code of a close frame, if it carried one. */
	close_code?: number | null,
	/**  The start of the payload for the list: text as is, binary empty. */
	preview: string,
};

/**
 *  One WebSocket message (fragmented messages are reassembled). The payload
 *  itself is fetched with `websocket_payload`.
 */
export type WsMessage_Serialize = {
	/**  Position in the flow's message list, from 0. */
	index: number,
	direction: WsDirection,
	opcode: WsOpcode,
	/**  Payload size in bytes. For close frames, the reason only. */
	len: number,
	/**  When the proxy received it, milliseconds since the Unix epoch. */
	time_ms: number | null,
	/**
	 *  True if only the first part of the payload was recorded (the cap is
	 *  1 MB per message). Forwarding is unaffected.
	 */
	truncated: boolean,
	/**  Status code of a close frame, if it carried one. */
	close_code: number | null,
	/**  The start of the payload for the list: text as is, binary empty. */
	preview: string,
};

export type WsOpcode = "text" | "binary" | "ping" | "pong" | "close";

/**  A window of a flow's WebSocket messages. */
export type WsPage = WsPage_Serialize | WsPage_Deserialize;

/**  A window of a flow's WebSocket messages. */
export type WsPage_Deserialize = {
	/**  Messages in the flow. */
	total: number,
	/**  Messages matching the query. */
	len: number,
	start: number,
	messages: WsMessage_Deserialize[],
	/**  False once the connection has closed. */
	open: boolean,
	close?: WsClose | null,
};

/**  A window of a flow's WebSocket messages. */
export type WsPage_Serialize = {
	/**  Messages in the flow. */
	total: number,
	/**  Messages matching the query. */
	len: number,
	start: number,
	messages: WsMessage_Serialize[],
	/**  False once the connection has closed. */
	open: boolean,
	close: WsClose | null,
};

/**  Which messages of a flow to list. The default lists everything. */
export type WsQuery = WsQuery_Serialize | WsQuery_Deserialize;

/**  Which messages of a flow to list. The default lists everything. */
export type WsQuery_Deserialize = {
	direction?: WsDirection | null,
	/**  Case-insensitive substring of the payload; empty matches everything. */
	text: string,
};

/**  Which messages of a flow to list. The default lists everything. */
export type WsQuery_Serialize = {
	direction: WsDirection | null,
	/**  Case-insensitive substring of the payload; empty matches everything. */
	text: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

